async function open(manage=false,lineId='',direction='',pattern=''){if(!canLeave())return;dirty=false;lastFocus=document.activeElement;if(!dialog.open)dialog.showModal();setMapLayersMenuOpen(false);initMap();await window.tracksideAppReady;const ok=await loadNetwork(false);if(manage&&admin()){$('busNetworkManagement').open=true;$('busNetworkManagement').scrollIntoView({block:'start'});}if(!ok)return;if(lineId){routeSearch.value='';populateRoutes(lineId);directionChoice.value=direction;populatePatterns();patternChoice.value=pattern;}await scan();busMap.invalidateSize();fitRoute();}
