function exportCsv(){const rows=[['Network version','Network verification','Effective date','Route ID','Route name','Infrastructure ID','Project','Agency','Jurisdiction','Potential impact','Geometry basis','Location confidence','Distance feet','Directions and patterns','Stop IDs','Construction phases','Simultaneous windows','Source']];const windows=combinedWindows();for(const f of visible)rows.push([network.fingerprint,network.verification_status,network.effective_date||'Not supplied',f.line_id,selectedRoute().line_name,f.project_id,f.project_name,f.agency,f.jurisdiction,C.label,f.geometry_basis,f.geometry_confidence,Math.round(f.distance_m/.3048),scopedAlignments(f).map(a=>a.dir_name+' / '+a.pattern+' / '+a.dir_id).join(' | '),f.stop_ids.join(' | '),f.windows.map(windowText).join(' | '),windows.filter(w=>w.project_ids.includes(f.project_id)).map(w=>new Date(w.first).toISOString().slice(0,10)+' → '+new Date(w.last).toISOString().slice(0,10)+' '+w.certainty+' '+w.physical).join(' | '),f.source_url]);const url=URL.createObjectURL(new Blob([T.csv(rows)],{type:'text/csv;charset=utf-8'})),a=N('a');a.href=url;a.download='trackside-local-bus-impacts.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
statusChoice.parentElement.hidden=decisionChoice.parentElement.hidden=!admin();setupImport();$('busRefresh').addEventListener('click',async()=>{if(!canLeave())return;dirty=false;if(await loadNetwork(true)){await scan(true);fitRoute();}});$('busFit').addEventListener('click',fitRoute);$('busClear').addEventListener('click',()=>{if(!canLeave())return;dirty=false;clearFilters();});$('busExport').addEventListener('click',exportCsv);$('busShowStops').addEventListener('change',paintDetailStops);
networkChoice.addEventListener('change',async()=>{if(!canLeave()){networkChoice.value=network.fingerprint;return;}dirty=false;if(!await loadNetwork(false,networkChoice.value)){if(network)networkChoice.value=network.fingerprint;return;}await scan();fitRoute();});routeSearch.addEventListener('input',debounce(()=>{if(dirty)return;populateRoutes();if(routeChoice.value!==lastScope)scan().then(fitRoute);}));routeChoice.addEventListener('change',async()=>{if(!canLeave()){routeChoice.value=lastScope;return;}dirty=false;selected=null;directionChoice.value=patternChoice.value='';populatePatterns();await scan();fitRoute();});distanceChoice.dataset.previous=distanceChoice.value;distanceChoice.addEventListener('change',()=>{if(!canLeave()){distanceChoice.value=distanceChoice.dataset.previous;return;}distanceChoice.dataset.previous=distanceChoice.value;dirty=false;scan();});
for(const input of [directionChoice,patternChoice,agencyChoice,jurisdictionChoice,statusChoice,decisionChoice,dateStart,dateFinish]){input.addEventListener('focus',()=>input.dataset.previous=input.value);input.addEventListener('change',()=>{if(!canLeave()){input.value=input.dataset.previous||'';return;}dirty=false;page=0;if(input===directionChoice)populatePatterns();render();input.dataset.previous=input.value;});}
const priorLayerCount=updateMapLayersCount;updateMapLayersCount=function(){priorLayerCount();const badge=$('mapLayersCount'),button=$('mapLayersButton');if(badge&&button){const count=Number(badge.textContent)+(mainToggle.checked?1:0)+(mainToggle.checked&&mainStopToggle.checked?1:0);badge.textContent=String(count);button.setAttribute('aria-label','Map layers, '+count+' visible');}};
mainToggle.addEventListener('change',async()=>{if(mainToggle.checked)await loadNetwork();paintMain();updateMapLayersCount();});mainSearch.addEventListener('input',debounce(paintMain));mainStopToggle.addEventListener('change',()=>{updateMapLayersCount();if(mainStopToggle.checked&&!mainToggle.checked){mainToggle.checked=true;updateMapLayersCount();loadNetwork().then(paintMain);}else paintMainStops();});map.on('moveend zoomend',oncePerFrame(paintMainStops));
window.addEventListener('trackside:infrastructure-loaded',()=>{if(dialog.open&&!loadingSources&&!dirty&&network)scan(false);});function metadataDraft(){return admin()&&network&&(($('busNetworkEffectiveDate')?.value||'')!==(network.effective_date||'')||($('busNetworkVerification')?.value||'unverified')!==network.verification_status||($('busNetworkVerificationNote')?.value||'')!==(network.verification_note||'')||$('busModeEvidence')?.value||$('busModeSource')?.value);}
window.addEventListener('focus',async()=>{
  if((!dialog.open&&!mainToggle.checked)||dirty||screening||metadataDraft()||Date.now()-networkCheckedAt<FOCUS_CHECK_INTERVAL)return;
  const old=networkSignature();
  if(!await loadNetwork(true,'',true))return;
  if(dialog.open&&!dirty&&!screening&&!metadataDraft()&&(old!==networkSignature()||Date.now()-lastScanAt>300000))await scan(false);
});
const priorAdmin=updateAdminUi;updateAdminUi=function(...args){const value=priorAdmin(...args);adminEntry.hidden=!admin();$('busNetworkManagement').hidden=!admin();if(!admin()){reviews.clear();reviewReady=false;dirty=false;statusChoice.value=decisionChoice.value='';renderDetail();renderSaved();}renderManagement();if(dialog.open){if(admin())loadReviews().then(render);else render();}return value;};
window.TracksideLocalBus={open,refresh:()=>scan(true),get network(){return network;},get findings(){return baseFindings;},get visibleFindings(){return visible;}};
